const team = {
  members: [],
  size: 0,
  join(name) {
    this.members.push(name);
    this.size += 1;
  },
};

const red = Object.create(team);
const blue = Object.create(team);

red.join("Ada");
blue.join("Kim");
blue.join("Lin");

console.log(red.size, blue.size, team.size);
console.log(red.members.length, team.members.join(","));
console.log(Object.hasOwn(red, "members"), Object.hasOwn(red, "size"));
